    @Test
    void adjudicateRequestIdReplayAndDifferentParamsReturn409() throws Exception {
        createObservation("req-o14", "obs-1", "站点A", "1.0", "备注");
        createFence("req-f11", "fence-1", "site-1", "31.0", "32.0", "121.0", "122.0",
