        String firstBody = adjudicate("sub-1", "req-a7", "op-review", "ACCEPT", "理由一")
                .andExpect(status().isOk())
                .andReturn().getResponse().getContentAsString();
        // 同参重放：返回首次完整响应快照
        String replayBody = adjudicate("sub-1", "req-a7", "op-review", "ACCEPT", "理由一")
