        adjudicate("sub-1", "req-a2", "op-review", "ACCEPT", "再次裁决")
                .andExpect(status().isConflict());
    }

    @Test
    void adjudicateValidationFailures() throws Exception {
        createObservation("req-o12", "obs-1", "站点A", "1.0", "备注");
