            item("sub-3", "obs-2", "site-1", 1, "站点B2", "2.5", "备注",
                    31.5, 121.5, "2026-09-15T08:00:00Z")))
            .andExpect(status().isGone());
    assertThat(submissionCount()).isZero();
}

