15	/**
16	 * 离线观测提交与人工裁决业务服务。
17	 *
18	 * <p>批量提交在单事务内完成：先对全部提交项做坐标语义校验（任一非法整批 422 回滚），
19	 * 再按提交顺序逐项裁决——按采集时刻匹配站点当前生效围栏（生效区间 UTC 左闭右开，
20	 * 矩形边界含端点）；落围栏内的项按原三方合并规则自动合并进观测记录，
21	 * 落围栏外的项保存为 GEOFENCE_REJECTED，不参与自动合并但保留原始证据。
22	 * 观测记录不存在/已删除/基线版本缺失/合并冲突时整批回滚，查询不到半成品。
23	 *
24	 * <p>提交的原始坐标、采集/提交时刻与匹配结果不可变；后续围栏改版不重算历史匹配结果。
25	 * 人工裁决仅可接受 GEOFENCE_REJECTED 提交且必须填写理由，裁决时按提交保存的候选值
26	 * 与基线版本重算三方合并；裁决记录不可变，一次提交至多一条。
27	 *
28	 * <p>requestId 同参重放返回首次完整响应快照、异参 409、失败不占键；
29	 * 幂等指纹包含操作者、操作类型、规范化提交项集合及所有影响结果的字段。
30	 */
31	@Service
32	public class SubmissionService {
33	
34	    private final SubmissionRepository submissionRepository;
35	    private final AdjudicationRepository adjudicationRepository;
36	    private final ObservationRepository observationRepository;
37	    private final GeofenceRepository geofenceRepository;
38	    private final IdempotentRequests idempotentRequests;
39	    private final Fingerprinting fingerprinting;
40	    private final Clock clock;
41	
42	    public SubmissionService(SubmissionRepository submissionRepository,
43	                             AdjudicationRepository adjudicationRepository,
44	                             ObservationRepository observationRepository,
45	                             GeofenceRepository geofenceRepository,
46	                             IdempotentRequests idempotentRequests,
47	                             Fingerprinting fingerprinting,
48	                             Clock clock) {
49	        this.submissionRepository = submissionRepository;
50	        this.adjudicationRepository = adjudicationRepository;
51	        this.observationRepository = observationRepository;
52	        this.geofenceRepository = geofenceRepository;
53	        this.idempotentRequests = idempotentRequests;
54	        this.fingerprinting = fingerprinting;
55	        this.clock = clock;
56	    }
57	
58	    /**
59	     * 批量离线提交：任一格式/语义错误整批回滚；成功时逐项落库并返回逐项裁决结果。
60	     */
61	    @Transactional
62	    public BatchOutcome submitBatch(BatchSubmitObservationsRequest request) {
63	        // 先校验完整最终状态：全部提交项坐标合法、批内 submissionId 不重复，再进入写流程
64	        Set<String> seenSubmissionIds = new HashSet<>();
65	        for (SubmissionItemRequest item : request.items()) {
66	            GeoValidation.validatePoint(item.latitude(), item.longitude());
67	            if (!seenSubmissionIds.add(item.submissionId())) {
68	                throw ApiException.badRequest("duplicate submissionId within batch: " + item.submissionId());
69	            }
70	        }
71	
72	        String fingerprint = fingerprinting.of("SUBMIT_BATCH", request.operator(), itemParts(request.items()));
73	        RequestLogEntry existing = idempotentRequests.findExistingOrThrow(request.requestId(), fingerprint);
74	        if (existing != null) {
75	            return replayBatch(existing);
76	        }
77	        RequestLogEntry concurrent = idempotentRequests.insertPlaceholderOrNull(
78	                request.requestId(), fingerprint, "SUBMIT_BATCH");
79	        if (concurrent != null) {
80	            return replayBatch(concurrent);
81	        }
82	
83	        Instant submittedAt = Instant.now(clock);
84	
85	        // 统一按排序顺序获取全部站点锁与观测记录行锁，再按提交顺序处理：
86	        // 站点锁保证批次处理期间该站点围栏配置不变（与围栏创建/改版串行化），
87	        // 排序加锁避免多站点批次间的死锁；行锁在本事务内可重入，处理时再次锁定无副作用。
88	        request.items().stream()
89	                .map(SubmissionItemRequest::siteId)
90	                .distinct()
91	                .sorted()
92	                .forEach(geofenceRepository::lockSiteForUpdate);
93	        request.items().stream()
94	                .map(SubmissionItemRequest::observationId)
95	                .distinct()
96	                .sorted()
97	                .forEach(observationId -> observationRepository.findCurrentForUpdate(observationId)
98	                        .orElseThrow(() -> ApiException.notFound(
99	                                "observation not found: " + observationId)));
100	
101	        List<SubmissionResponse> results = new ArrayList<>();
102	        int itemIndex = 0;
103	        for (SubmissionItemRequest item : request.items()) {
104	            results.add(processItem(request, item, itemIndex, submittedAt));
105	            itemIndex++;
106	        }
107	        BatchSubmissionResponse body = new BatchSubmissionResponse(
108	                request.requestId(), request.operator(), submittedAt, results);
109	        idempotentRequests.complete(request.requestId(), HttpStatus.OK.value(), body);
110	        return new BatchOutcome(HttpStatus.OK.value(), body);
111	    }
112	
113	    /**
114	     * 人工裁决：接受围栏拒绝的提交。须写理由；仅 GEOFENCE_REJECTED 可裁决；
115	     * 裁决时按提交保存的候选值与基线版本重算三方合并，冲突则 409 不写任何结果。
116	     */
117	    @Transactional
118	    public AdjudicationOutcome adjudicate(String submissionId, AdjudicateSubmissionRequest request) {
119	        if (!"ACCEPT".equals(request.decision())) {
120	            throw ApiException.badRequest("decision must be ACCEPT: " + request.decision());
121	        }
122	        if (request.reason().isBlank()) {
123	            throw ApiException.badRequest("reason must not be blank");
124	        }
125	        String fingerprint = fingerprinting.of("ADJUDICATE", submissionId, request.operator(),
126	                request.decision(), request.reason());
127	        RequestLogEntry existing = idempotentRequests.findExistingOrThrow(request.requestId(), fingerprint);
128	        if (existing != null) {
129	            return replayAdjudication(existing);
130	        }
131	        RequestLogEntry concurrent = idempotentRequests.insertPlaceholderOrNull(
132	                request.requestId(), fingerprint, "ADJUDICATE");
133	        if (concurrent != null) {
134	            return replayAdjudication(concurrent);
135	        }
136	
137	        SubmissionRecord submission = submissionRepository.findForUpdate(submissionId)
138	                .orElseThrow(() -> ApiException.notFound("submission not found: " + submissionId));
139	        if (adjudicationRepository.findBySubmissionId(submissionId).isPresent()) {
140	            throw ApiException.conflict("submission already adjudicated: " + submissionId, null);
141	        }
142	        if (!SubmissionRecord.STATUS_GEOFENCE_REJECTED.equals(submission.matchStatus())) {
143	            throw ApiException.conflict(
144	                    "only GEOFENCE_REJECTED submissions can be adjudicated: " + submissionId
145	                            + " (matchStatus " + submission.matchStatus() + ")", null);
146	        }
147	
148	        ObservationSnapshot current = observationRepository.findCurrentForUpdate(submission.observationId())
149	                .orElseThrow(() -> ApiException.notFound(
150	                        "observation not found: " + submission.observationId()));
151	        if (current.deleted()) {
152	            throw ApiException.gone("observation already deleted: " + submission.observationId());
153	        }
154	        ObservationSnapshot base = observationRepository.findVersion(
155	                submission.observationId(), submission.baseVersion())
156	                .orElseThrow(() -> ApiException.notFound(
157	                        "base version not found: " + submission.observationId()
158	                                + "@" + submission.baseVersion()));
159	
160	        int observationVersion = mergeIntoObservation(submission.observationId(), base, current,
161	                submission.location(), submission.reading(), submission.note());
162	        AdjudicationRecord record = new AdjudicationRecord(submissionId, request.requestId(),
163	                request.operator(), request.decision(), request.reason(),
164	                observationVersion, Instant.now(clock));
165	        try {
166	            adjudicationRepository.insert(record);
167	        } catch (DuplicateKeyException e) {
168	            // 并发裁决同一提交：主键串行化，后到者按已裁决处理
169	            throw ApiException.conflict("submission already adjudicated: " + submissionId, null);
170	        }
171	        AdjudicationResponse body = AdjudicationResponse.of(record, submission);
172	        idempotentRequests.complete(request.requestId(), HttpStatus.OK.value(), body);
173	        return new AdjudicationOutcome(HttpStatus.OK.value(), body);
174	    }
175	
176	    /**
177	     * 查询提交明细；不存在返回 404。
178	     */
179	    @Transactional(readOnly = true)
180	    public SubmissionResponse getSubmission(String submissionId) {
181	        return SubmissionResponse.of(submissionRepository.find(submissionId)
182	                .orElseThrow(() -> ApiException.notFound("submission not found: " + submissionId)));
183	    }
184	
185	    /**
186	     * 按观测记录查询提交历史，按提交时刻与提交标识升序；观测记录不存在返回 404。
187	     */
188	    @Transactional(readOnly = true)
189	    public List<SubmissionResponse> listByObservation(String observationId) {
190	        observationRepository.findCurrent(observationId)
191	                .orElseThrow(() -> ApiException.notFound("observation not found: " + observationId));
192	        return submissionRepository.findByObservationId(observationId).stream()
193	                .map(SubmissionResponse::of)
194	                .toList();
195	    }
196	
197	    /**
198	     * 按站点查询提交历史，按提交时刻与提交标识升序。
199	     */
200	    @Transactional(readOnly = true)
201	    public List<SubmissionResponse> listBySite(String siteId) {
202	        return submissionRepository.findBySiteId(siteId).stream()
203	                .map(SubmissionResponse::of)
204	                .toList();
205	    }
206	
207	    /**
208	     * 站点提交诊断：各项数量均为实际值。
209	     */
210	    @Transactional(readOnly = true)
211	    public SubmissionDiagnosticsResponse diagnostics(String siteId) {
212	        int accepted = submissionRepository.countBySiteAndStatus(siteId, SubmissionRecord.STATUS_ACCEPTED);
213	        int rejected = submissionRepository.countBySiteAndStatus(
214	                siteId, SubmissionRecord.STATUS_GEOFENCE_REJECTED);
215	        int adjudicated = adjudicationRepository.countAcceptedBySite(siteId);
216	        return new SubmissionDiagnosticsResponse(siteId, accepted + rejected, accepted, rejected,
217	                adjudicated, rejected - adjudicated);
218	    }
219	
220	    /**
221	     * 处理单个提交项：围栏匹配 → 自动合并或保留拒绝证据，落库不可变提交记录。
222	     */
223	    private SubmissionResponse processItem(BatchSubmitObservationsRequest request,
224	                                           SubmissionItemRequest item, int itemIndex, Instant submittedAt) {
225	        ObservationSnapshot current = observationRepository.findCurrentForUpdate(item.observationId())
226	                .orElseThrow(() -> ApiException.notFound("observation not found: " + item.observationId()));
227	        if (current.deleted()) {
228	            throw ApiException.gone("observation already deleted: " + item.observationId());
229	        }
230	        ObservationSnapshot base = observationRepository.findVersion(item.observationId(), item.baseVersion())
231	                .orElseThrow(() -> ApiException.notFound(
232	                        "base version not found: " + item.observationId() + "@" + item.baseVersion()));
233	
234	        GeofenceVersionRecord matched = geofenceRepository.findMatching(
235	                item.siteId(), item.capturedAtUtc(), item.latitude(), item.longitude()).orElse(null);
236	        String matchStatus;
237	        String matchedFenceId = null;
238	        Integer matchedFenceVersion = null;
239	        Integer observationVersion = null;
240	        if (matched != null) {
241	            matchStatus = SubmissionRecord.STATUS_ACCEPTED;
242	            matchedFenceId = matched.fenceId();
243	            matchedFenceVersion = matched.version();
244	            observationVersion = mergeIntoObservation(item.observationId(), base, current,
245	                    item.location(), item.reading(), item.note());
246	        } else {
247	            // 落围栏外：保存 GEOFENCE_REJECTED 原始证据，不参与自动合并
248	            matchStatus = SubmissionRecord.STATUS_GEOFENCE_REJECTED;
249	        }
250	
251	        SubmissionRecord record = new SubmissionRecord(item.submissionId(), request.requestId(), itemIndex,
252	                request.operator(), item.observationId(), item.siteId(), item.baseVersion(),
253	                item.location(), item.reading(), item.note(),
254	                item.latitude(), item.longitude(), item.capturedAtUtc(), submittedAt,
255	                matchStatus, matchedFenceId, matchedFenceVersion, observationVersion);
256	        try {
257	            submissionRepository.insert(record);
258	        } catch (DuplicateKeyException e) {
259	            // submissionId 已被历史批次占用：整批 409 回滚
260	            throw ApiException.conflict("submissionId already exists: " + item.submissionId(), null);
261	        }
262	        return SubmissionResponse.of(record);
263	    }
264	
265	    /**
266	     * 三方合并候选值到观测记录：与离线合并同一套规则；冲突抛 409 不写部分结果，
267	     * 内容无变化不加版本。返回合并后观测记录版本号。
268	     */
269	    private int mergeIntoObservation(String observationId, ObservationSnapshot base,
270	                                     ObservationSnapshot current, String location,
271	                                     String reading, String note) {
272	        List<String> conflictFields = new ArrayList<>();
273	        String mergedLocation = ObservationService.mergeField("location", base.location(),
274	                current.location(), location, conflictFields);
275	        String mergedReading = ObservationService.mergeReadingField(base.reading(),
276	                current.reading(), reading, conflictFields);
277	        String mergedNote = ObservationService.mergeField("note", base.note(),
278	                current.note(), note, conflictFields);
279	        if (!conflictFields.isEmpty()) {
280	            throw ApiException.mergeConflict(conflictFields, current.version());
281	        }
282	        ObservationSnapshot merged = new ObservationSnapshot(observationId, current.version(),
283	                mergedLocation, mergedReading, mergedNote, false);
284	        if (ObservationService.sameContent(merged, current)) {
285	            return current.version();
286	        }
287	        ObservationSnapshot next = new ObservationSnapshot(observationId, current.version() + 1,
288	                mergedLocation, mergedReading, mergedNote, false);
289	        observationRepository.updateCurrent(next);
290	        observationRepository.insertVersion(next);
291	        return next.version();
292	    }
293	
294	    /**
295	     * 组装批量提交项的规范化指纹因子：每项按固定字段顺序展开，集合整体交给 JSON 转义序列化。
296	     */
297	    private List<List<Object>> itemParts(List<SubmissionItemRequest> items) {
298	        return items.stream()
299	                .<List<Object>>map(item -> List.of(item.submissionId(), item.observationId(), item.siteId(),
300	                        item.baseVersion(), item.location(), item.reading(), item.note(),
301	                        item.latitude(), item.longitude(), item.capturedAtUtc()))
302	                .toList();
303	    }
304	
305	    private BatchOutcome replayBatch(RequestLogEntry entry) {
306	        return new BatchOutcome(entry.responseStatus(),
307	                idempotentRequests.readStoredBody(entry, BatchSubmissionResponse.class));
308	    }
309	
310	    private AdjudicationOutcome replayAdjudication(RequestLogEntry entry) {
311	        return new AdjudicationOutcome(entry.responseStatus(),
312	                idempotentRequests.readStoredBody(entry, AdjudicationResponse.class));
313	    }
314	
315	    /**
316	     * 批量提交结果：HTTP 状态码与批量响应体。
317	     */
318	    public record BatchOutcome(int status, BatchSubmissionResponse body) {
319	    }
320	
321	    /**
322	     * 人工裁决结果：HTTP 状态码与裁决响应体。
323	     */
324	    public record AdjudicationOutcome(int status, AdjudicationResponse body) {
325	    }
326	}
